use std::collections::BTreeMap;

use ecow::{EcoString, eco_format};
use serde::Serialize;
use typst::diag::{At, Hint, HintedStrResult, SourceResult, bail};
use typst::foundations::{Dict, Label, Selector, Value, cast};
use typst::introspection::{Introspector, Location, MetadataElem, Tag};
use typst::syntax::VirtualPath;
use typst_bundle::{Bundle, BundleDocument, BundleFile};
use typst_html::{HtmlElement, HtmlNode};
use typst_utils::PicoStr;

/// A search index that is encoded as `search.json`, emitted as an asset, and
/// then fetched by the frontend to power the site-global search in the top
/// left.
#[derive(Debug, Serialize)]
pub struct SearchIndex {
    /// Items that can be potential search results.
    pub items: Vec<IndexItem>,
    /// A sorted list of words that occur in the docs. Can be binary searched
    /// to find prefix matches.
    pub words: Vec<String>,
    /// Parallel to `words`. Stores the indices of the `items` which contain
    /// the parallel word.
    pub hits: Vec<Vec<usize>>,
}

/// One item in the search index.
///
/// Corresponds to one possible match during search. Here are two examples:
/// ```json
/// {
///   "kind": "Function",
///   "title": "Heading",
///   "route": "/reference/model/heading/"
/// },
/// {
///   "kind": "Parameter of caption",
///   "title": "Separator",
///   "route": "/reference/model/figure/#definitions-caption-separator"
/// },
/// ```
#[derive(Debug, Clone, Serialize)]
pub struct IndexItem {
    /// The category of item. Shown next to the match.
    pub kind: EcoString,
    /// The title-case name of the item. Shown as the match.
    pub title: EcoString,
    /// The full route to the matching page. May include a fragment.
    pub route: EcoString,
    /// Keywords with which the page can be found. The keywords are stored in
    /// the item to aid with ranking.
    #[serde(skip_serializing_if = "Vec::is_empty")]
    pub keywords: Vec<EcoString>,
}

cast! {
    IndexItem,
    mut v: Dict => Self {
        kind: v.take("kind")?.cast()?,
        title: v.take("title")?.cast()?,
        route: v.take("route")?.cast()?,
        keywords: v.take("keywords")?.cast()?,
    }
}

/// Walks through the bundle and indexes all text and items in it. Items
/// are `metadata` elements labelled `<metadata-index-item>`. Text in between
/// items is considered belonging to the preceding item.
pub fn build_search_index(bundle: &Bundle) -> SourceResult<SearchIndex> {
    let mut indexer = Indexer::new();
    for file in bundle.files.values() {
        let BundleFile::Document(BundleDocument::Html(doc)) = file else { continue };
        walk_html(&mut indexer, doc.root(), bundle.introspector.as_ref())?;
    }
    Ok(indexer.finish())
}

/// Determines the path at which the search index should be emitted. This is a
/// bit roundabout because we can't contextually access the
/// `stdx.config.asset-base` configuration from the top level. So we do it in
/// Typst code instead and leave the result in `metadata`.
pub fn index_path(bundle: &Bundle) -> HintedStrResult<VirtualPath> {
    let path = bundle
        .introspector
        .query_unique(&Selector::Label(
            Label::new(PicoStr::intern("search-index-path")).unwrap(),
        ))?
        .to_packed::<MetadataElem>()
        .ok_or("expected metadata element")?
        .value
        .clone()
        .cast::<EcoString>()?;

    VirtualPath::new(&path).map_err(|_| "invalid path".into())
}

/// Indexes the contents of a single HTML element, recursively.
fn walk_html(
    indexer: &mut Indexer,
    elem: &HtmlElement,
    introspector: &dyn Introspector,
) -> SourceResult<()> {
    for node in &elem.children {
        match node {
            HtmlNode::Tag(tag) => {
                if let Tag::Start(it, _) = tag
                    && it.label() == Some(indexer.item_label)
                    && let Some(metadata) = it.to_packed::<MetadataElem>()
                {
                    let item = parse_item_metadata(metadata.value.clone(), introspector)
                        .hint("search index metadata is not well-formed")
                        .at(metadata.span())?;
                    indexer.enter(item.clone());
                    indexer.index_str(&item.title);
                    for keyword in &item.keywords {
                        indexer.index_str(keyword);
                    }
                }
            }
            HtmlNode::Text(text, _) => indexer.index_str(text),
            HtmlNode::Element(elem) => walk_html(indexer, elem, introspector)?,
            HtmlNode::Frame(_) => {}
        }
    }
    Ok(())
}

/// Takes a search index metadata element's dynamic value and turns it into
/// strongly typed index item.
fn parse_item_metadata(
    value: Value,
    introspector: &dyn Introspector,
) -> HintedStrResult<IndexItem> {
    let mut dict = value.cast::<Dict>()?;
    let kind = dict.take("kind")?.cast()?;
    let title = dict.take("title")?.cast()?;
    let dest = dict.take("dest")?.cast::<ItemDestination>()?;
    let keywords = dict.take("keywords")?.cast()?;
    let route = match dest {
        ItemDestination::Route(route) => {
            if !route.ends_with('/') {
                bail!("routes should end with a slash: {route:?}");
            }
            route
        }
        ItemDestination::Location(loc) => {
            let path = introspector.path(loc).ok_or("found no path for index item")?;
            let path = path
                .get_with_slash()
                .strip_suffix("index.html")
                .ok_or("expected consistent usage of index.html")?;
            let anchor = introspector
                .anchor(loc)
                .ok_or("found no HTML anchor for index item")?;
            if anchor.is_empty() { path.into() } else { eco_format!("{path}#{anchor}") }
        }
    };
    Ok(IndexItem { kind, title, route, keywords })
}

/// The two kinds of destinations that can be stored in an index item's
/// `dest` field.
enum ItemDestination {
    /// A raw route to an HTML file. Must end with a slash.
    Route(EcoString),
    /// A location that should be resolved to a route.
    Location(Location),
}

cast! {
   ItemDestination,
   v: EcoString => Self::Route(v),
   v: Location => Self::Location(v),
}

/// Associates text with index items.
struct Indexer {
    words: BTreeMap<String, Vec<usize>>,
    items: Vec<IndexItem>,
    item_label: Label,
}

impl Indexer {
    fn new() -> Self {
        Self {
            words: BTreeMap::new(),
            items: vec![],
            item_label: Label::new(PicoStr::intern("metadata-index-item")).unwrap(),
        }
    }

    fn finish(self) -> SearchIndex {
        let mut words = vec![];
        let mut hits = vec![];
        for (word, word_hits) in self.words {
            words.push(word);
            hits.push(word_hits);
        }
        SearchIndex { items: self.items, words, hits }
    }

    fn enter(&mut self, item: IndexItem) {
        self.items.push(item);
    }

    fn index_str(&mut self, s: &str) {
        if self.items.is_empty() {
            return;
        }
        let n = self.items.len() - 1;
        for word in s
            .to_lowercase()
            .split(|c: char| c.is_ascii_whitespace() || c.is_ascii_punctuation())
            .filter(|w| !w.is_empty())
            .filter(|w| STOP_WORDS.binary_search(w).is_err())
        {
            let vec = self.words.entry(word.into()).or_default();
            if !vec.contains(&n) {
                vec.push(n);
            }
        }
    }
}

/// These words are ignored. Taken from
/// <https://gist.github.com/sebleier/554280>.
#[rustfmt::skip]
const STOP_WORDS: &[&str] = &[
    "a", "about", "am", "an", "and", "are", "as", "at", "be", "because", "been",
    "being", "but", "by", "can", "did", "do", "does", "doing", "don", "few",
    "from", "had", "has", "have", "he", "her", "hers", "herself", "him",
    "himself", "his", "i", "into", "is", "it", "its", "itself", "just", "me",
    "more", "most", "my", "myself", "no", "nor", "not", "now", "or", "our",
    "ours", "ourselves", "out", "s", "she", "should", "so", "some", "such", "t",
    "than", "that", "the", "their", "theirs", "them", "themselves", "then",
    "there", "these", "they", "this", "those", "to", "too", "very", "was", "we",
    "were", "what", "who", "whom", "why", "will", "you", "your", "yours",
    "yourself", "yourselves",
];

use typst_syntax::Spanned;

use crate::diag::SourceResult;
use crate::engine::Engine;
use crate::foundations::{
    Cast, Content, Derived, Label, Packed, Smart, StyleChain, Synthesize, cast, elem,
};
use crate::model::bibliography::Works;
use crate::model::{CslSource, CslStyle};
use crate::text::{Lang, Region, TextElem};

/// Cite a work from the bibliography.
///
/// Before you starting citing, you need to add a @bibliography[bibliography]
/// somewhere in your document.
///
/// = Example <example>
/// ```example
/// This was already noted by
/// pirates long ago. @arrgh
///
/// Multiple sources say ...
/// @arrgh @netwok.
///
/// You can also call `cite`
/// explicitly. #cite(<arrgh>)
///
/// #bibliography("works.bib")
/// ```
///
/// If your source name contains certain characters such as slashes, which are
/// not recognized by the `<>` syntax, you can explicitly call `label` instead.
///
/// ```typ
/// Computer Modern is an example of a modernist serif typeface.
/// #cite(label("DBLP:books/lib/Knuth86a")).
/// ```
///
/// = Syntax <syntax>
/// This function indirectly has dedicated syntax. @ref[References] can be used
/// to cite works from the bibliography. The label then corresponds to the
/// citation key.
#[elem(since = "forever", Locatable, Synthesize)]
pub struct CiteElem {
    /// The citation key that identifies the entry in the bibliography that
    /// shall be cited, as a label.
    ///
    /// ```example
    /// // All the same
    /// @netwok \
    /// #cite(<netwok>) \
    /// #cite(label("netwok"))
    /// >>> #set text(0pt)
    /// >>> #bibliography("works.bib", style: "apa")
    /// ```
    #[required]
    pub key: Label,

    /// A supplement for the citation such as page or chapter number.
    ///
    /// In reference syntax, the supplement can be added in square brackets:
    ///
    /// ```example
    /// This has been proven. @distress[p.~7]
    ///
    /// #bibliography("works.bib")
    /// ```
    pub supplement: Option<Content>,

    /// The kind of citation to produce. Different forms are useful in different
    /// scenarios: A normal citation is useful as a source at the end of a
    /// sentence, while a "prose" citation is more suitable for inclusion in the
    /// flow of text.
    ///
    /// If set to `{none}`, the cited work is included in the bibliography, but
    /// nothing will be displayed.
    ///
    /// ```example
    /// #cite(<netwok>, form: "prose")
    /// show the outsized effects of
    /// pirate life on the human psyche.
    /// >>> #set text(0pt)
    /// >>> #bibliography("works.bib", style: "apa")
    /// ```
    #[default(Some(CitationForm::Normal))]
    pub form: Option<CitationForm>,

    /// The citation style.
    ///
    /// This can be:
    /// - `{auto}` to automatically use the
    ///   @bibliography.style[bibliography's style] for citations.
    /// - A string with the name of one of the built-in styles (see below). Some
    ///   of the styles listed below appear twice, once with their full name and
    ///   once with a short alias.
    /// - A path string or @path to a
    ///   #link("https://citationstyles.org/")[CSL file].
    /// - Raw bytes from which a CSL style should be decoded.
    #[parse(match args.named::<Spanned<Smart<CslSource>>>("style")? {
        Some(Spanned { v: Smart::Custom(source), span }) => Some(Smart::Custom(
            CslStyle::load(engine, Spanned::new(source, span))?
        )),
        Some(Spanned { v: Smart::Auto, .. }) => Some(Smart::Auto),
        None => None,
    })]
    pub style: Smart<Derived<CslSource, CslStyle>>,

    /// The text language setting where the citation is.
    #[internal]
    #[synthesized]
    pub lang: Lang,

    /// The text region setting where the citation is.
    #[internal]
    #[synthesized]
    pub region: Option<Region>,
}

impl Synthesize for Packed<CiteElem> {
    fn synthesize(&mut self, _: &mut Engine, styles: StyleChain) -> SourceResult<()> {
        let elem = self.as_mut();
        elem.lang = Some(styles.get(TextElem::lang));
        elem.region = Some(styles.get(TextElem::region));
        Ok(())
    }
}

cast! {
    CiteElem,
    v: Content => v.unpack::<Self>().map_err(|_| "expected citation")?,
}

/// The form of the citation.
#[derive(Debug, Default, Copy, Clone, Eq, PartialEq, Hash, Cast)]
pub enum CitationForm {
    /// Display in the standard way for the active style.
    #[default]
    Normal,
    /// Produces a citation that is suitable for inclusion in a sentence.
    Prose,
    /// Mimics a bibliography entry, with full information about the cited work.
    Full,
    /// Shows only the cited work's author(s).
    Author,
    /// Shows only the cited work's year.
    Year,
}

/// A group of consecutive citations.
///
/// This element is automatically created from adjacent citations during
/// realization. Citations are grouped without regard to which bibliography they
/// end up being assigned to. They are only split into subgroups during
/// bibliography assignment within the call tree of [`Works::generate`].
///
/// Each subgroup created there may consist of one or multiple citations that
/// are processed as a union by hayagriva. If hayagriva were to support a single
/// citation group for multiple bibliographies, the subgroup concept could be
/// removed, but it's unclear whether that can be reasonably supported.
///
/// Another alternative would have been to already segment by assigned
/// bibliography when grouping consecutive citations into [`CiteGroup`]s during
/// realization. This would be quite clean, but unfortunately it would incur one
/// additional document iteration, which is too high a price to pay for the
/// conceptual cleanliness.
///
/// The citation group element is purposefully kept internal to retain
/// flexibility in how it is collected.
#[elem(Locatable)]
pub struct CiteGroup {
    /// Holds citations and potentially spaces in between them. The spaces are
    /// retained so that they can be correctly rendered between subgroups
    /// assigned to different bibliographies.
    #[required]
    pub children: Vec<Content>,
}

impl Packed<CiteGroup> {
    pub fn realize(&self, engine: &mut Engine) -> SourceResult<Content> {
        let loc = self.location().unwrap();
        let span = self.span();
        Works::generate(engine, span)?.citation(loc, span)
    }
}

// Defines metadata for docs search in the web version.
//
// Cooperates with `docs/src/search.rs`.

#import "base.typ": labelled

// Defines one searchable entry (a search _index item_) in the documentation,
// i.e. one potential search hit.
//
// See `IndexItem` in the Rust sources for more details on the parameters.
#let register-index-item(
  kind: none,
  title: none,
  dest: none,
  keywords: (),
) = labelled(
  metadata((
    kind: kind,
    title: title,
    dest: dest,
    keywords: keywords,
  )),
  <metadata-index-item>,
)

// Test emph and strong.

--- emph-syntax paged ---
// Basic.
_Emphasized and *strong* words!_

// Inside of a word it's a normal underscore or star.
hello_world Nutzer*innen

// CJK characters will not need spaces.
中文一般使用*粗体*或者_楷体_来表示强调。

日本語では、*太字*や_斜体_を使って強調します。

中文中混有*Strong*和_Emphasis_。

// Can contain paragraph in nested content block.
_Still #[

] emphasized._

--- emph-and-strong-call-in-word paged ---
// Inside of words can still use the functions.
P#strong[art]ly em#emph[phas]ized.

--- emph-empty-hint paged empty ---
// Warning: 1-3 no text within underscores
// Hint: 1-3 using multiple consecutive underscores (e.g. __) has no additional effect
__

--- emph-double-underscore-empty-hint paged ---
// Warning: 1-3 no text within underscores
// Hint: 1-3 using multiple consecutive underscores (e.g. __) has no additional effect
// Warning: 13-15 no text within underscores
// Hint: 13-15 using multiple consecutive underscores (e.g. __) has no additional effect
__not italic__

--- emph-unclosed eval ---
// Error: 6-7 unclosed delimiter
#box[_Scoped] to body.

--- emph-ends-at-parbreak eval ---
// Ends at paragraph break.
// Error: 1-2 unclosed delimiter
_Hello

World

--- emph-strong-unclosed-nested eval ---
// Error: 11-12 unclosed delimiter
// Error: 3-4 unclosed delimiter
#[_Cannot *be interleaved]

--- strong-delta paged ---
// Adjusting the delta that strong applies on the weight.
Normal

#set strong(delta: 300)
*Bold*

#set strong(delta: 150)
*Medium* and *#[*Bold*]*

--- strong-empty-hint paged empty ---
// Warning: 1-3 no text within stars
// Hint: 1-3 using multiple consecutive stars (e.g. **) has no additional effect
**

--- strong-double-star-empty-hint paged ---
// Warning: 1-3 no text within stars
