--- asset-log bundle ---
#let log(..s) = [#metadata(s.pos().join("", default: ""))<log>]

#let compute-and-display(x) = {
  log("Start")
  let x = 1
  for _ in range(5) {
    x += x
    log("x = ", str(x))
  }
  log("End")
  [x is #x]
}

#document("index.html", compute-and-display(5))

#context asset(
  "log.txt",
  query(<log>).map(it => it.value).join("\n", default: ""),
)
